// HAND-WRITTEN TEST — NOT generated by openapi-generator.
//
// This file must survive every regeneration of the model package: it is
// named with a zz_ prefix and an _test.go suffix so the generator (which
// only emits model_*.go) never overwrites it, and so it never ships in a
// non-test build.
//
// Purpose: prove that every oneOf wrapper decoder in this package round-trips
// every variant. The package ships fourteen wrappers — the twelve platform
// attribute unions shared with every other connector spec, plus the two
// key-creation unions specific to Cryptography Provider v2. Twelve of them
// have a discriminator-aware UnmarshalJSON patched in by tools/fixoneof (see
// that tool's `wrappers` table); the generator's stock "try every variant,
// count strict matches" decoder fails on those because multiple variants
// share the same Go struct shape and all pass strict decode at once. These
// tests lock in the patched behaviour so a future regen that forgets to
// re-run fixoneof — or a fixoneof change that breaks a variant — fails
// loudly here.
//
// Dispatch model (mirrors the Java wire contract encoded in tools/fixoneof):
//
//   - BaseAttributeDto (outer) and MetadataAttribute switch on a NUMERIC
//     `version` (2 -> V2, 3 -> V3); a missing version defaults to V2. The
//     version marshals as a JSON number, so the round-trip discriminator is
//     `"version":2` / `"version":3`.
//   - BaseAttributeDtoV2 / BaseAttributeDtoV3 (inner) switch on the string
//     `type` (custom/data/group/info/meta).
//   - RequestAttribute switches on the string `version` ("v2"/"v3"), missing
//     defaults to RequestAttributeV2. ResponseAttribute switches on the same
//     string `version` but has NO default.
//   - BaseAttributeConstraint switches on `type` (dateTime/range/regExp),
//     missing defaults to RegexpAttributeConstraint.
//   - BaseAttributeContentDtoV3 (contentType), SecretContent (type),
//     ResourceObjectContentData (resource) and FieldMappingFieldsInner
//     (fieldType) switch on their respective string discriminators.
//   - KeyCreationResponse and KeyCreationStatusResponse switch on the string
//     `keyRequestType` ("secret" / "keyPair").
//
// For every variant of every discriminator wrapper the table below asserts:
//   a. json.Unmarshal(payload) into the wrapper succeeds,
//   b. GetActualInstance() returns the expected concrete variant type,
//   c. json.Marshal(wrapper) succeeds and re-emits the discriminator
//      key/value,
//   d. json.Unmarshal of those marshalled bytes into a FRESH wrapper yields
//      the same variant type (a full encode/decode round-trip).
// Plus a negative test per wrapper: an unknown discriminator value must
// error with a message mentioning "unknown". That message is the tripwire —
// the stock decoder reports an ambiguous or failed match instead, and never
// the word "unknown".
//
// The three wrappers that carry a Java "defaultImpl" (BaseAttributeDto,
// RequestAttribute, BaseAttributeConstraint) additionally have a dedicated
// test proving the missing-discriminator payload ROUTES to the documented
// default variant. See the DEFAULT-ROUTING note above those tests for why a
// bare payload cannot fully round-trip through the default branch.
//
// One non-discriminator oneOf lives in this package and still uses the
// generator's match-counting decoder (a tools/fixoneof knownUnpatchable
// entry — the spec defines NO discriminator, so every case is provably
// un-decodable and documented inline with t.Skip):
//
//   - BaseAttributeContentDtoV2 — every variant shares {reference?, data} and
//     ObjectAttributeContentV2 types data as interface{}, so all cases collide.
//
// The final section covers the seven properties the spec pins to a single
// value, whose enforcement tools/fixoneof writes into the generated code
// (see tools/fixoneof/pins.go). The generator drops both spellings of a pin
// — a `$ref` with a sibling one-element `enum`, and a bare `const` — so
// without those guards this package could marshal a document its own
// decoder rejects.

package v2

import (
	"encoding/json"
	"fmt"
	"reflect"
	"strings"
	"testing"
)

// oneOfCase describes a single happy-path expectation for a discriminator
// wrapper: a payload, the new-wrapper allocator, the expected concrete
// variant type, and a discriminator substring the marshalled form must
// contain.
type oneOfCase struct {
	name string
	// payload is a minimal-but-valid JSON document satisfying the variant's
	// required fields (field names/types taken from the generated models).
	payload string
	// newWrapper returns a fresh pointer to the wrapper type under test as a
	// json.Unmarshaler / GetActualInstance provider.
	newWrapper func() oneOfWrapper
	// wantType is a zero value of the expected concrete variant (pointer);
	// GetActualInstance must return a value of the same dynamic type.
	wantType interface{}
	// discSubstr must appear in the marshalled JSON (the discriminator
	// key:value pair), proving the discriminator survives a round-trip.
	discSubstr []string
}

// oneOfWrapper is the common surface every generated oneOf wrapper exposes.
type oneOfWrapper interface {
	json.Unmarshaler
	json.Marshaler
	GetActualInstance() interface{}
}

// runDiscriminatorCases drives steps (a)-(d) for one wrapper's happy-path
// cases. wrapperName is used only for failure messages.
func runDiscriminatorCases(t *testing.T, wrapperName string, cases []oneOfCase) {
	t.Helper()
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			wantT := reflect.TypeOf(tc.wantType)

			// (a) Unmarshal the payload into the wrapper.
			w := tc.newWrapper()
			if err := json.Unmarshal([]byte(tc.payload), w); err != nil {
				t.Fatalf("%s: unmarshal payload failed: %v\npayload: %s", wrapperName, err, tc.payload)
			}

			// (b) GetActualInstance returns the expected variant type.
			got := w.GetActualInstance()
			if got == nil {
				t.Fatalf("%s: GetActualInstance returned nil after decoding %s", wrapperName, tc.name)
			}
			if gotT := reflect.TypeOf(got); gotT != wantT {
				t.Fatalf("%s: GetActualInstance type = %v, want %v", wrapperName, gotT, wantT)
			}

			// (c) Marshal the wrapper; output must carry the discriminator.
			b, err := json.Marshal(w)
			if err != nil {
				t.Fatalf("%s: marshal failed: %v", wrapperName, err)
			}
			for _, sub := range tc.discSubstr {
				if !strings.Contains(string(b), sub) {
					t.Fatalf("%s: marshalled JSON missing discriminator %q\ngot: %s", wrapperName, sub, b)
				}
			}

			// (d) Round-trip: decode the marshalled bytes into a fresh
			// wrapper and confirm the same variant comes back.
			w2 := tc.newWrapper()
			if err := json.Unmarshal(b, w2); err != nil {
				t.Fatalf("%s: round-trip unmarshal failed: %v\nbytes: %s", wrapperName, err, b)
			}
			got2 := w2.GetActualInstance()
			if got2 == nil {
				t.Fatalf("%s: round-trip GetActualInstance returned nil", wrapperName)
			}
			if gotT := reflect.TypeOf(got2); gotT != wantT {
				t.Fatalf("%s: round-trip type = %v, want %v", wrapperName, gotT, wantT)
			}
		})
	}
}

// assertUnknownDiscriminator confirms a wrapper rejects an unknown
// discriminator value with an error mentioning "unknown".
func assertUnknownDiscriminator(t *testing.T, wrapperName string, w json.Unmarshaler, payload string) {
	t.Helper()
	err := json.Unmarshal([]byte(payload), w)
	if err == nil {
		t.Fatalf("%s: expected error for unknown discriminator, got nil", wrapperName)
	}
	if !strings.Contains(err.Error(), "unknown") {
		t.Fatalf("%s: error %q does not mention \"unknown\"", wrapperName, err.Error())
	}
}

// assertDefaultRoutes confirms a wrapper whose Java contract carries a
// defaultImpl routes a discriminator-less payload to the documented default
// variant. The generated Go models enforce the discriminator field as a
// required property on that variant, so a bare payload routes to the default
// branch and then fails the required-property check — the error names the
// default variant, which is exactly the routing proof we want. wantVariant is
// the concrete-type name expected in the decode-path error.
//
// If a future spec/regen makes the discriminator optional on the default
// variant, this payload will start to decode and the test trips, prompting a
// promotion to a happy-path case in the table above.
func assertDefaultRoutes(t *testing.T, wrapperName string, w json.Unmarshaler, payload, wantVariant string) {
	t.Helper()
	err := json.Unmarshal([]byte(payload), w)
	if err == nil {
		t.Fatalf("%s: discriminator-less payload unexpectedly decoded — the default "+
			"variant %s may have made the discriminator optional; promote this to a "+
			"happy-path case", wrapperName, wantVariant)
	}
	if !strings.Contains(err.Error(), wantVariant) {
		t.Fatalf("%s: default-routing error %q does not name expected variant %q",
			wrapperName, err.Error(), wantVariant)
	}
	if !strings.Contains(err.Error(), "required property") {
		t.Fatalf("%s: default-routing error %q is not the expected required-property failure",
			wrapperName, err.Error())
	}
}

// --- Reusable minimal payload fragments --------------------------------------

// fullProps satisfies the required fields of DataAttributeProperties and
// CustomAttributeProperties.
const fullProps = `{"label":"L","visible":true,"required":true,"readOnly":false,"list":false,"multiSelect":false,"extensibleList":false}`

// infoMetaProps satisfies InfoAttributeProperties / MetadataAttributeProperties
// (only label+visible required).
const infoMetaProps = `{"label":"L","visible":true}`

// 1. BaseAttributeContentDtoV3 — discriminator "contentType" (12 variants).
func TestOneOfBaseAttributeContentDtoV3(t *testing.T) {
	cases := []oneOfCase{
		{
			name:       "boolean",
			payload:    `{"contentType":"boolean","data":true}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeContentDtoV3{} },
			wantType:   &BooleanAttributeContentV3{},
			discSubstr: []string{`"contentType":"boolean"`},
		},
		{
			name:       "codeblock",
			payload:    `{"contentType":"codeblock","data":{"language":"bash","code":"echo hi"}}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeContentDtoV3{} },
			wantType:   &CodeBlockAttributeContentV3{},
			discSubstr: []string{`"contentType":"codeblock"`},
		},
		{
			name:       "date",
			payload:    `{"contentType":"date","data":"2026-06-04"}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeContentDtoV3{} },
			wantType:   &DateAttributeContentV3{},
			discSubstr: []string{`"contentType":"date"`},
		},
		{
			name:       "datetime",
			payload:    `{"contentType":"datetime","data":"2026-06-04T10:00:00Z"}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeContentDtoV3{} },
			wantType:   &DateTimeAttributeContentV3{},
			discSubstr: []string{`"contentType":"datetime"`},
		},
		{
			name:       "file",
			payload:    `{"contentType":"file","data":{"content":"YQ==","fileName":"f.txt","mimeType":"text/plain"}}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeContentDtoV3{} },
			wantType:   &FileAttributeContentV3{},
			discSubstr: []string{`"contentType":"file"`},
		},
		{
			name:       "float",
			payload:    `{"contentType":"float","data":1.5}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeContentDtoV3{} },
			wantType:   &FloatAttributeContentV3{},
			discSubstr: []string{`"contentType":"float"`},
		},
		{
			name:       "integer",
			payload:    `{"contentType":"integer","data":7}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeContentDtoV3{} },
			wantType:   &IntegerAttributeContentV3{},
			discSubstr: []string{`"contentType":"integer"`},
		},
		{
			name:       "object",
			payload:    `{"contentType":"object","data":{"any":"thing"}}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeContentDtoV3{} },
			wantType:   &ObjectAttributeContentV3{},
			discSubstr: []string{`"contentType":"object"`},
		},
		{
			name:       "resource",
			payload:    `{"contentType":"resource","data":{"resource":"authorities","uuid":"u","name":"n"}}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeContentDtoV3{} },
			wantType:   &ResourceObjectContent{},
			discSubstr: []string{`"contentType":"resource"`},
		},
		{
			name:       "string",
			payload:    `{"contentType":"string","data":"hello"}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeContentDtoV3{} },
			wantType:   &StringAttributeContentV3{},
			discSubstr: []string{`"contentType":"string"`},
		},
		{
			name:       "text",
			payload:    `{"contentType":"text","data":"a longer text"}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeContentDtoV3{} },
			wantType:   &TextAttributeContentV3{},
			discSubstr: []string{`"contentType":"text"`},
		},
		{
			name:       "time",
			payload:    `{"contentType":"time","data":"10:00:00"}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeContentDtoV3{} },
			wantType:   &TimeAttributeContentV3{},
			discSubstr: []string{`"contentType":"time"`},
		},
	}
	runDiscriminatorCases(t, "BaseAttributeContentDtoV3", cases)

	assertUnknownDiscriminator(t, "BaseAttributeContentDtoV3",
		&BaseAttributeContentDtoV3{}, `{"contentType":"bogus","data":"x"}`)
}

// 2. BaseAttributeDtoV3 — discriminator "type" (custom/data/group/info/meta).
// The concrete V3 attribute types carry a numeric `version` (int32) and a
// required schemaVersion="v3"; the version value is irrelevant to the inner
// `type` dispatch but is set to 3 to mirror a realistic V3 payload.
func TestOneOfBaseAttributeDtoV3(t *testing.T) {
	cases := []oneOfCase{
		{
			name:       "custom",
			payload:    `{"type":"custom","uuid":"u","name":"n","version":3,"contentType":"string","properties":` + fullProps + `,"schemaVersion":"v3"}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeDtoV3{} },
			wantType:   &CustomAttributeV3{},
			discSubstr: []string{`"type":"custom"`, `"schemaVersion":"v3"`},
		},
		{
			name:       "data",
			payload:    `{"type":"data","uuid":"u","name":"n","version":3,"contentType":"string","properties":` + fullProps + `,"schemaVersion":"v3"}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeDtoV3{} },
			wantType:   &DataAttributeV3{},
			discSubstr: []string{`"type":"data"`, `"schemaVersion":"v3"`},
		},
		{
			name:       "group",
			payload:    `{"type":"group","uuid":"u","name":"n","schemaVersion":"v3"}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeDtoV3{} },
			wantType:   &GroupAttributeV3{},
			discSubstr: []string{`"type":"group"`, `"schemaVersion":"v3"`},
		},
		{
			name:       "info",
			payload:    `{"type":"info","uuid":"u","name":"n","content":[{"contentType":"string","data":"x"}],"contentType":"string","properties":` + infoMetaProps + `,"schemaVersion":"v3"}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeDtoV3{} },
			wantType:   &InfoAttributeV3{},
			discSubstr: []string{`"type":"info"`, `"schemaVersion":"v3"`},
		},
		{
			name:       "meta",
			payload:    `{"type":"meta","uuid":"u","name":"n","version":3,"contentType":"string","properties":` + infoMetaProps + `,"schemaVersion":"v3"}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeDtoV3{} },
			wantType:   &MetadataAttributeV3{},
			discSubstr: []string{`"type":"meta"`, `"schemaVersion":"v3"`},
		},
	}
	runDiscriminatorCases(t, "BaseAttributeDtoV3", cases)

	assertUnknownDiscriminator(t, "BaseAttributeDtoV3",
		&BaseAttributeDtoV3{}, `{"type":"bogus","uuid":"u","name":"n","schemaVersion":"v3"}`)
}

// 3. BaseAttributeDtoV2 — discriminator "type" (custom/data/group/info/meta).
// V2 variants carry no schemaVersion field; the numeric `version` is set to 2
// to mirror a realistic V2 payload (it does not drive the inner `type` dispatch).
func TestOneOfBaseAttributeDtoV2(t *testing.T) {
	cases := []oneOfCase{
		{
			name:       "custom",
			payload:    `{"type":"custom","uuid":"u","name":"n","version":2,"contentType":"string","properties":` + fullProps + `}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeDtoV2{} },
			wantType:   &CustomAttributeV2{},
			discSubstr: []string{`"type":"custom"`},
		},
		{
			name:       "data",
			payload:    `{"type":"data","uuid":"u","name":"n","version":2,"contentType":"string","properties":` + fullProps + `}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeDtoV2{} },
			wantType:   &DataAttributeV2{},
			discSubstr: []string{`"type":"data"`},
		},
		{
			name:       "group",
			payload:    `{"type":"group","uuid":"u","name":"n","version":2}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeDtoV2{} },
			wantType:   &GroupAttributeV2{},
			discSubstr: []string{`"type":"group"`},
		},
		// NOTE: the "info" variant (InfoAttributeV2) is intentionally absent
		// from this happy-path table. InfoAttributeV2 *requires* a `content`
		// array of BaseAttributeContentDtoV2, and that nested oneOf is the
		// un-decodable match-counting wrapper (see
		// TestOneOfBaseAttributeContentDtoV2). Decoding an info V2 payload
		// therefore fails transitively. That broken case is pinned by
		// TestOneOfBaseAttributeDtoV2InfoBrokenByDesign below.
		{
			name:       "meta",
			payload:    `{"type":"meta","uuid":"u","name":"n","version":2,"contentType":"string","properties":` + infoMetaProps + `}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeDtoV2{} },
			wantType:   &MetadataAttributeV2{},
			discSubstr: []string{`"type":"meta"`},
		},
	}
	runDiscriminatorCases(t, "BaseAttributeDtoV2", cases)

	assertUnknownDiscriminator(t, "BaseAttributeDtoV2",
		&BaseAttributeDtoV2{}, `{"type":"bogus","uuid":"u","name":"n","version":2}`)
}

// TestOneOfBaseAttributeDtoV2InfoBrokenByDesign pins the transitive breakage
// of the info V2 variant. BaseAttributeDtoV2's discriminator decode for
// "info" succeeds in *selecting* InfoAttributeV2, but InfoAttributeV2 then
// requires a `content` array whose element type is the un-decodable
// match-counting BaseAttributeContentDtoV2 oneOf. So a realistic info V2
// payload fails decoding deep inside the nested content oneOf with the
// "matches more than one schema" error, regardless of the (correct) outer
// type discriminator. This is collateral damage from
// knownUnpatchable[BaseAttributeContentDtoV2]; fixing the V2 content oneOf
// (spec discriminator) would also unblock this case.
func TestOneOfBaseAttributeDtoV2InfoBrokenByDesign(t *testing.T) {
	const infoV2 = `{"type":"info","uuid":"u","name":"n","version":2,"content":[{"data":"x"}],"contentType":"string","properties":` + infoMetaProps + `}`
	var w BaseAttributeDtoV2
	err := json.Unmarshal([]byte(infoV2), &w)
	if err == nil {
		t.Fatalf("BaseAttributeDtoV2 info: expected failure decoding nested V2 content, got %T", w.GetActualInstance())
	}
	if !strings.Contains(err.Error(), "matches more than one schema") {
		t.Fatalf("BaseAttributeDtoV2 info: expected nested ambiguous-match error, got %q", err.Error())
	}
	t.Skip("InfoAttributeV2 requires a content array of BaseAttributeContentDtoV2, " +
		"the un-decodable match-counting oneOf (see TestOneOfBaseAttributeContentDtoV2). " +
		"Fix the V2 content oneOf's spec discriminator to unblock.")
}

// 4. BaseAttributeDto — discriminator NUMERIC "version" (2 -> V2, 3 -> V3).
//
// The Java BaseAttributeSerializer writes a numeric `version` (2/3), which
// tools/fixoneof reads as the wire discriminator (NOT the schemaVersion string
// the OpenAPI declares). The concrete attribute types carry that same
// `version` as a required int32, so it survives the marshal round-trip as a
// JSON number — the round-trip discriminator asserted here is `"version":2` /
// `"version":3`. A missing version defaults to V2; that default-routing path
// is covered by TestOneOfBaseAttributeDtoDefaultVersion below.
func TestOneOfBaseAttributeDto(t *testing.T) {
	cases := []oneOfCase{
		{
			name:       "v2",
			payload:    `{"version":2,"type":"data","uuid":"u","name":"n","contentType":"string","properties":` + fullProps + `}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeDto{} },
			wantType:   &BaseAttributeDtoV2{},
			discSubstr: []string{`"version":2`},
		},
		{
			name:       "v3",
			payload:    `{"version":3,"type":"data","uuid":"u","name":"n","contentType":"string","properties":` + fullProps + `,"schemaVersion":"v3"}`,
			newWrapper: func() oneOfWrapper { return &BaseAttributeDto{} },
			wantType:   &BaseAttributeDtoV3{},
			discSubstr: []string{`"version":3`},
		},
	}
	runDiscriminatorCases(t, "BaseAttributeDto", cases)

	// Unknown numeric version value.
	assertUnknownDiscriminator(t, "BaseAttributeDto",
		&BaseAttributeDto{}, `{"version":9,"type":"data","uuid":"u","name":"n"}`)
}

// TestOneOfBaseAttributeDtoDefaultVersion covers the missing-version default.
//
// DEFAULT-ROUTING: tools/fixoneof defaults a missing `version` to "2", routing
// a version-less payload to BaseAttributeDtoV2 (Java defaultImpl parity). Every
// generated V2 attribute type, however, declares `version` as a REQUIRED
// property, so the bare payload routes to the V2 branch and then fails that
// required-property check. This test proves the routing (the error is raised
// on the BaseAttributeDtoV2 decode path) and pins the fact that a bare payload
// cannot fully round-trip through the default branch — a genuine Go-vs-Java
// divergence, not a fixable-in-test bug. Making `version` optional on the V2
// models (spec change) would let this promote to a happy-path case.
func TestOneOfBaseAttributeDtoDefaultVersion(t *testing.T) {
	const noVersion = `{"type":"data","uuid":"u","name":"n","contentType":"string","properties":` + fullProps + `}`
	var w BaseAttributeDto
	assertDefaultRoutes(t, "BaseAttributeDto", &w, noVersion, "BaseAttributeDtoV2")
}

// 5. MetadataAttribute — discriminator NUMERIC "version" (2 -> V2, 3 -> V3).
// Same numeric-version selector as BaseAttributeDto (Java BaseAttributeSerializer);
// a missing version defaults to V2. The concrete types carry `version` as a
// required int32, so it marshals back as a JSON number for the round-trip.
// (MetadataAttribute has a generated wrapper only in cryptography/v1.)
func TestOneOfMetadataAttribute(t *testing.T) {
	cases := []oneOfCase{
		{
			name:       "v2",
			payload:    `{"version":2,"type":"meta","uuid":"u","name":"n","contentType":"string","properties":` + infoMetaProps + `}`,
			newWrapper: func() oneOfWrapper { return &MetadataAttribute{} },
			wantType:   &MetadataAttributeV2{},
			discSubstr: []string{`"version":2`},
		},
		{
			name:       "v3",
			payload:    `{"version":3,"type":"meta","uuid":"u","name":"n","contentType":"string","properties":` + infoMetaProps + `,"schemaVersion":"v3"}`,
			newWrapper: func() oneOfWrapper { return &MetadataAttribute{} },
			wantType:   &MetadataAttributeV3{},
			discSubstr: []string{`"version":3`},
		},
	}
	runDiscriminatorCases(t, "MetadataAttribute", cases)

	assertUnknownDiscriminator(t, "MetadataAttribute",
		&MetadataAttribute{}, `{"version":9,"type":"meta","uuid":"u","name":"n"}`)
}

