// --- Pinned properties -------------------------------------------------------
//
// Seven properties in cryptography-v2.json admit exactly one value: the
// `keyRequestType` discriminator on each of the four key-creation variants
// (published as a $ref with a sibling one-element enum) and the `type` role
// tag on each of the three key-data descriptors (published as a const). The Go
// generator drops both spellings, so tools/fixoneof writes the enforcement in.
//
// The three tests below cover the three places it writes: the constructor
// (correct by construction), ToMap (cannot emit a value it would refuse to
// read), and UnmarshalJSON (rejects a mismatched value on the wire).

// pinnedProperty is one spec-pinned property, named the way the failure
// messages name it, with the JSON documents that must be accepted and
// rejected for it.
type pinnedProperty struct {
	name string
	// constructed is the value the generated constructor returns; its pinned
	// property must already hold the pinned value.
	constructed interface{}
	// pinnedValue is the only value the spec admits.
	pinnedValue string
	// mismatched carries a deliberately wrong value for the pinned property
	// and must fail to marshal.
	mismatched interface{}
	// decodeInto is a fresh pointer for the decode-rejection case.
	decodeInto func() interface{}
	// badPayload is a document whose pinned property holds the wrong value.
	badPayload string
}

func pinnedProperties() []pinnedProperty {
	return []pinnedProperty{
		{
			name:        "KeyPairDataResponseV2Dto.keyRequestType",
			constructed: NewKeyPairDataResponseV2Dto().KeyRequestType,
			pinnedValue: "keyPair",
			mismatched:  KeyPairDataResponseV2Dto{KeyRequestType: KEYREQUESTTYPE_SECRET},
			decodeInto:  func() interface{} { return &KeyPairDataResponseV2Dto{} },
			badPayload:  `{"keyRequestType":"secret"}`,
		},
		{
			name:        "SecretKeyDataResponseV2Dto.keyRequestType",
			constructed: NewSecretKeyDataResponseV2Dto().KeyRequestType,
			pinnedValue: "secret",
			mismatched:  SecretKeyDataResponseV2Dto{KeyRequestType: KEYREQUESTTYPE_KEY_PAIR},
			decodeInto:  func() interface{} { return &SecretKeyDataResponseV2Dto{} },
			badPayload:  `{"keyRequestType":"keyPair"}`,
		},
		{
			name:        "KeyPairOperationStatusResponseV2Dto.keyRequestType",
			constructed: NewKeyPairOperationStatusResponseV2Dto(OPERATIONSTATUS_COMPLETED).KeyRequestType,
			pinnedValue: "keyPair",
			mismatched: KeyPairOperationStatusResponseV2Dto{
				Status:         OPERATIONSTATUS_COMPLETED,
				KeyRequestType: KEYREQUESTTYPE_SECRET,
			},
			decodeInto: func() interface{} { return &KeyPairOperationStatusResponseV2Dto{} },
			badPayload: `{"keyRequestType":"secret","status":"completed"}`,
		},
		{
			name:        "SecretKeyOperationStatusResponseV2Dto.keyRequestType",
			constructed: NewSecretKeyOperationStatusResponseV2Dto(OPERATIONSTATUS_COMPLETED).KeyRequestType,
			pinnedValue: "secret",
			mismatched: SecretKeyOperationStatusResponseV2Dto{
				Status:         OPERATIONSTATUS_COMPLETED,
				KeyRequestType: KEYREQUESTTYPE_KEY_PAIR,
			},
			decodeInto: func() interface{} { return &SecretKeyOperationStatusResponseV2Dto{} },
			badPayload: `{"keyRequestType":"keyPair","status":"completed"}`,
		},
		{
			name:        "PrivateKeyDataV2Dto.type",
			constructed: NewPrivateKeyDataV2Dto(KEYALGORITHM_RSA, 3072).Type,
			pinnedValue: "Private",
			mismatched: PrivateKeyDataV2Dto{
				Type:      "Public",
				Algorithm: KEYALGORITHM_RSA,
				Length:    3072,
			},
			decodeInto: func() interface{} { return &PrivateKeyDataV2Dto{} },
			badPayload: `{"type":"Public","algorithm":"RSA","length":3072}`,
		},
		{
			name:        "PublicKeyDataV2Dto.type",
			constructed: NewPublicKeyDataV2Dto(KEYALGORITHM_RSA, 3072, "MIIB").Type,
			pinnedValue: "Public",
			mismatched: PublicKeyDataV2Dto{
				Type:          "Private",
				Algorithm:     KEYALGORITHM_RSA,
				Length:        3072,
				PublicKeySpki: "MIIB",
			},
			decodeInto: func() interface{} { return &PublicKeyDataV2Dto{} },
			badPayload: `{"type":"Private","algorithm":"RSA","length":3072,"publicKeySpki":"MIIB"}`,
		},
		{
			name:        "SecretKeyDataV2Dto.type",
			constructed: NewSecretKeyDataV2Dto(KEYALGORITHM_RSA, 2048).Type,
			pinnedValue: "Secret",
			mismatched: SecretKeyDataV2Dto{
				Type:      "Private",
				Algorithm: KEYALGORITHM_RSA,
				Length:    2048,
			},
			decodeInto: func() interface{} { return &SecretKeyDataV2Dto{} },
			badPayload: `{"type":"Private","algorithm":"RSA","length":2048}`,
		},
	}
}

// TestPinnedPropertiesSetByConstructor proves the constructor supplies the
// pinned value, which is what lets it drop the corresponding parameter — a
// caller can no longer pass the wrong one.
func TestPinnedPropertiesSetByConstructor(t *testing.T) {
	for _, tc := range pinnedProperties() {
		t.Run(tc.name, func(t *testing.T) {
			if got := fmt.Sprintf("%v", tc.constructed); got != tc.pinnedValue {
				t.Fatalf("%s: constructor set %q, want %q", tc.name, got, tc.pinnedValue)
			}
		})
	}
}

// TestPinnedPropertiesRejectedOnMarshal is the round-trip guarantee: a value
// carrying anything other than the pinned one must not reach the wire, since
// this package's own decoder would reject the document it produced.
func TestPinnedPropertiesRejectedOnMarshal(t *testing.T) {
	for _, tc := range pinnedProperties() {
		t.Run(tc.name, func(t *testing.T) {
			b, err := json.Marshal(tc.mismatched)
			if err == nil {
				t.Fatalf("%s: marshalling a mismatched value succeeded: %s", tc.name, b)
			}
			if !strings.Contains(err.Error(), tc.pinnedValue) {
				t.Fatalf("%s: error %q does not name the pinned value %q",
					tc.name, err.Error(), tc.pinnedValue)
			}
		})
	}
}

// TestPinnedPropertiesRejectedOnUnmarshal covers the decode side. It also
// makes each variant self-disambiguating: a document for one variant no
// longer strict-decodes as its sibling.
func TestPinnedPropertiesRejectedOnUnmarshal(t *testing.T) {
	for _, tc := range pinnedProperties() {
		t.Run(tc.name, func(t *testing.T) {
			err := json.Unmarshal([]byte(tc.badPayload), tc.decodeInto())
			if err == nil {
				t.Fatalf("%s: decoding %s succeeded", tc.name, tc.badPayload)
			}
			if !strings.Contains(err.Error(), tc.pinnedValue) {
				t.Fatalf("%s: error %q does not name the pinned value %q",
					tc.name, err.Error(), tc.pinnedValue)
			}
		})
	}
}
